<div class="admin-page-title"><div><span class="eyebrow">CONTAS E ACESSOS</span><h1>Usuários</h1><p>Consulte clientes, contas e histórico individual.</p></div><a class="btn btn-red" href="<?= h(url('admin/index.php?secao=usuario_form')) ?>">+ Novo usuário</a></div><div class="admin-card"><div class="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Telefone</th><th>Tipo</th><th>Situação</th><th>Histórico</th><th>Ações</th></tr></thead><tbody><?php foreach($usuarios as $u): ?><tr><td><b><?= h($u['nome']) ?></b></td><td><?= h($u['email']) ?></td><td><?= h($u['telefone']) ?></td><td><?= $u['tipo']==='admin'?'Administrador':'Cliente' ?></td><td><span class="status <?= $u['ativo']?'ativo':'cancelado' ?>"><?= $u['ativo']?'Ativo':'Desativado' ?></span></td><td><a class="link-button" href="<?= h(url('admin/index.php?secao=usuario_detalhes&id='.(int)$u['id'])) ?>">Ver histórico</a></td><td class="actions-cell"><a class="link-button" href="<?= h(url('admin/index.php?secao=usuario_form&id='.(int)$u['id'])) ?>">Editar</a><?php if($u['tipo']!=='admin' && $u['ativo']): ?><form method="post" action="<?= h(url('admin/controllers/acao.php')) ?>" onsubmit="return confirm('Desativar esta conta?')"><?= csrf_field() ?><input type="hidden" name="acao" value="delete_user"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="link-button danger-text">Desativar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
